question.solution:
def dec_to_base(n, base):
    digits = '0123456789ABCDEF'
    if n == 0:
        return '0'
    stack = []
    while n > 0:
        stack.append(n % base)
        n //= base
    out = []
    while stack:
        out.append(digits[stack.pop()])
    return ''.join(out)

print(dec_to_base(10, 2))
print(dec_to_base(255, 16))
print(dec_to_base(0, 2))
print(dec_to_base(1000000, 16))
